--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be a UPROPERTY: NewObject results are unreachable unless the
	// garbage collector sees the reference, and an unreferenced tracker is
	// purged, leaving a dangling pointer (see Saved/Logs shipping log).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker in AArenaGameMode was a raw pointer with no UPROPERTY() marker. It is created with NewObject in BeginPlay and never rooted, so the garbage collector sees no reference to it and purges it (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13). The next goal calls OnGoalScored -> ScoreTracker->AddPoints() on the dangling pointer, giving the fatal EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) at 21:05:27. It survives in the editor only because the editor's GC timing and extra references keep the object alive. Fixed by making ScoreTracker a UPROPERTY() TObjectPtr so it is reachable and tracked.",
  "no_colors_cause": "The palette asset is loaded by hardcoded string path, LoadObject<UArenaPalette>(nullptr, TEXT(\"/Game/Data/Palettes/DA_Primary.DA_Primary\")), so the cooker sees no reference to it. Config/DefaultGame.ini has bCookAll=False, cooks only /Game/Maps/Arena plus /Game/Data/Effects, and /Game/Data/Palettes is not in DirectoriesToAlwaysCook, so DA_Primary is never packaged. The packaged build therefore fails to load it (log: 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'Failed to find object ArenaPalette /Game/Data/Palettes/DA_Primary'), Palette stays null and the HUD falls back to gray ('Palette is null, using fallback gray'). The editor shows colors because every asset is available there. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini.",
  "fixes": [
    "Source/PixelArena/ArenaGameMode.h: ScoreTracker is now UPROPERTY() TObjectPtr<UArenaScoreTracker>, so the GC keeps it alive while the game mode references it.",
    "Config/DefaultGame.ini: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") so DA_Primary is cooked into the packaged build."
  ],
  "evidence": [
    "Saved/Logs/PixelArena-shipping.log line 4: LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary requested by async loading code.",
    "Saved/Logs/PixelArena-shipping.log line 6: LogArena: Warning: Palette is null, using fallback gray.",
    "Saved/Logs/PixelArena-shipping.log line 8: LogGarbage: Collecting garbage: 412 objects purged (21:05:13, before the crash).",
    "Saved/Logs/PixelArena-shipping.log lines 12-14: Fatal EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints called from AArenaGameMode::OnGoalScored (21:05:27, after the purge)."
  ],
  "assumptions": [
    "The packaged build was built from these sources; the log's OnGoalScored line number (38) differs slightly from the current file (36), consistent with the shipped revision.",
    "ArenaScoreTracker.cpp and the palette/HUD assets exist in the full project and are correct; only the reachability of the tracker and the cook scope of the palette are wrong here.",
    "Cooking /Game/Data/Palettes is acceptable (small primary-palette data); the alternative, a UPROPERTY soft/hard object reference set in an editor asset, cannot be done without the editor on this machine."
  ]
}
